package com.example.demo.nuscenes.storage;

import java.io.*;
import java.nio.channels.Channels;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.http.ContentStreamProvider;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;

/** One archive at a time is admitted by UploadArchiveStore; at most concurrency parts are in flight. */
final class MultipartArchiveUploader implements AutoCloseable {
 static final long PART_BYTES=16L*1024*1024, THRESHOLD_BYTES=64L*1024*1024;
 private static final Logger LOG=LoggerFactory.getLogger(MultipartArchiveUploader.class);
 private final S3Client s3;
 private final int concurrency;
 private final ExecutorService workers;

 MultipartArchiveUploader(S3Client s3,int concurrency) {
  if(concurrency<1 || concurrency>4)throw new IllegalArgumentException("S3 upload concurrency must be 1..4");
  this.s3=s3;this.concurrency=concurrency;
  workers=Executors.newFixedThreadPool(concurrency,r->{var t=new Thread(r,"s3-archive-part");t.setDaemon(true);return t;});
 }

 void upload(String bucket,String key,Path source,String contentType,long size,String attempt) throws IOException {
  String uploadId=s3.createMultipartUpload(CreateMultipartUploadRequest.builder().bucket(bucket).key(key)
   .contentType(contentType).metadata(Map.of("ds2l-upload-attempt",attempt))
   .checksumAlgorithm(ChecksumAlgorithm.CRC32).checksumType(ChecksumType.COMPOSITE)
   .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(30))).build()).uploadId();
  LOG.info("[S3_TRANSFER] stage=multipart_create key={} upload_id={} concurrency={}",key,uploadId,concurrency);
  var completion=new ExecutorCompletionService<CompletedPart>(workers);
  var inFlight=new HashSet<Future<CompletedPart>>();
  var parts=new ArrayList<CompletedPart>();
  boolean interrupted=false;
  try {
   int count=Math.toIntExact((size+PART_BYTES-1)/PART_BYTES),next=1;
   while(next<=count || !inFlight.isEmpty()) {
    checkInterrupted();
    while(next<=count && inFlight.size()<concurrency) {
     int number=next++;
     inFlight.add(completion.submit(()->part(bucket,key,uploadId,source,number,Math.min(PART_BYTES,size-(number-1)*PART_BYTES))));
    }
    Future<CompletedPart> finished=completion.take();
    inFlight.remove(finished);parts.add(finished.get());
   }
   parts.sort(Comparator.comparingInt(CompletedPart::partNumber));
   // A completion signal can win the queue wait race and return with the
   // interrupt flag set. Do not rely on take()/get() alone to cancel a commit.
   checkInterrupted();
   s3.completeMultipartUpload(CompleteMultipartUploadRequest.builder().bucket(bucket).key(key).uploadId(uploadId)
    .multipartUpload(CompletedMultipartUpload.builder().parts(parts).build())
    .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(60))).build());
  } catch(Exception failure) {
   // Always clear the flag while draining/cleaning up, even when failure itself
   // is InterruptedException. Restore it only after the S3 cleanup calls finish.
   interrupted=Thread.interrupted();
   interrupted|=failure instanceof InterruptedException;
   // Future.cancel reports completion before blocking HTTP has stopped. Drain the actual
   // calls before aborting so a late UploadPart cannot recreate stored parts after cleanup.
   for(Future<CompletedPart> future:inFlight) {
    boolean done=false;
    while(!done)try { future.get();done=true; }
    catch(InterruptedException again) { interrupted=true; }
    catch(ExecutionException|CancellationException ignored) { done=true; }
   }
   // A successful Complete response may have been lost. Match this attempt only;
   // never delete or accept an older object at the same key.
   if(committed(bucket,key,size,attempt)) {
    LOG.info("[S3_TRANSFER] stage=multipart_reconcile key={} result=committed",key);
    return;
   }
   try { abortAndVerify(bucket,key,uploadId); }
   catch(RuntimeException cleanup) {
    failure.addSuppressed(cleanup);
    LOG.error("[S3_TRANSFER] stage=multipart_abort key={} upload_id={} result=unconfirmed error={}",key,uploadId,cleanup.getClass().getSimpleName());
   }
   if(failure instanceof RuntimeException runtime)throw runtime;
   throw new IOException(interrupted?"S3 archive upload interrupted":"S3 multipart upload failed",failure);
  } finally {
   if(interrupted)Thread.currentThread().interrupt();
  }
 }

 private static void checkInterrupted() throws InterruptedException {
  if(Thread.interrupted())throw new InterruptedException("S3 multipart upload interrupted before completion");
 }

 private CompletedPart part(String bucket,String key,String uploadId,Path source,int number,long bytes) throws IOException {
  long start=System.nanoTime();
  try(var slice=new FileSlice(source,(number-1)*PART_BYTES,bytes)) {
   var response=s3.uploadPart(UploadPartRequest.builder().bucket(bucket).key(key).uploadId(uploadId).partNumber(number)
    .contentLength(bytes).checksumAlgorithm(ChecksumAlgorithm.CRC32)
    .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(120)).apiCallAttemptTimeout(Duration.ofSeconds(60))).build(),
    RequestBody.fromContentProvider(slice,bytes,"application/octet-stream"));
   LOG.info("[S3_TRANSFER] stage=upload_part key={} part={} bytes={} wall_ms={} status={} request_id={}",
    key,number,bytes,(System.nanoTime()-start)/1_000_000,response.sdkHttpResponse().statusCode(),response.responseMetadata().requestId());
   return CompletedPart.builder().partNumber(number).eTag(response.eTag()).checksumCRC32(response.checksumCRC32()).build();
  }
 }

 private boolean committed(String bucket,String key,long size,String attempt) {
  try {
   var head=s3.headObject(HeadObjectRequest.builder().bucket(bucket).key(key)
    .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(30))).build());
   return Objects.equals(head.contentLength(),size) && attempt.equals(head.metadata().get("ds2l-upload-attempt"));
  } catch(RuntimeException unavailable) { return false; }
 }

 private void abortAndVerify(String bucket,String key,String uploadId) {
  for(int retry=0;retry<3;retry++) {
   try { s3.abortMultipartUpload(AbortMultipartUploadRequest.builder().bucket(bucket).key(key).uploadId(uploadId)
     .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(30))).build()); }
   catch(S3Exception missing) { if(missing.statusCode()!=404)throw missing; }
   try { s3.listParts(ListPartsRequest.builder().bucket(bucket).key(key).uploadId(uploadId).maxParts(1)
     .overrideConfiguration(c->c.apiCallTimeout(Duration.ofSeconds(30))).build()); }
   catch(S3Exception missing) {
    if(missing.statusCode()!=404)throw missing;
    LOG.info("[S3_TRANSFER] stage=multipart_abort key={} upload_id={} result=verified_absent",key,uploadId);
    return;
   }
  }
  throw new IllegalStateException("Multipart cleanup could not be confirmed");
 }

 @Override public void close() { workers.shutdown(); }

 /** Reopens exactly the same file range for SDK retries; never buffers a whole part/file. */
 static final class FileSlice implements ContentStreamProvider,AutoCloseable {
  private final Path path;private final long offset,length;private InputStream current;
  FileSlice(Path path,long offset,long length) { this.path=path;this.offset=offset;this.length=length; }
  @Override public InputStream newStream() {
   try {
    close();var channel=Files.newByteChannel(path,StandardOpenOption.READ);
    try { channel.position(offset); }catch(IOException error) { channel.close();throw error; }
    current=new FilterInputStream(Channels.newInputStream(channel)) {
     private long remaining=length;
     @Override public int read() throws IOException { byte[] one=new byte[1];return read(one,0,1)<0?-1:one[0]&255; }
     @Override public int read(byte[] b,int off,int len) throws IOException {
      if(len==0)return 0;if(remaining==0)return -1;
      int count=in.read(b,off,(int)Math.min(len,remaining));
      if(count<0)throw new EOFException("Archive changed or was truncated during upload");
      remaining-=count;return count;
     }
     @Override public long skip(long n) throws IOException { long skipped=in.skip(Math.min(Math.max(n,0),remaining));remaining-=skipped;return skipped; }
     @Override public int available() throws IOException { return (int)Math.min(in.available(),remaining); }
    };
    return current;
   }catch(IOException failure) { throw new UncheckedIOException(failure); }
  }
  @Override public void close() throws IOException { if(current!=null) { current.close();current=null; } }
 }
}

package com.example.demo.nuscenes.storage;

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import software.amazon.awssdk.core.ResponseInputStream;
import software.amazon.awssdk.core.sync.RequestBody;
import software.amazon.awssdk.http.SdkHttpResponse;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class S3ArchiveTransferTests {
 @TempDir Path root;
 private static final String BUCKET="fixture-bucket",KEY="uploads/"+UUID.randomUUID()+".tar.gz";
 private S3Client client;
 @BeforeEach void setup() {
  client=mock(S3Client.class);
  when(client.createMultipartUpload(any(CreateMultipartUploadRequest.class))).thenReturn(CreateMultipartUploadResponse.builder().uploadId("owned-upload").build());
  when(client.headObject(any(HeadObjectRequest.class))).thenThrow(NoSuchKeyException.builder().statusCode(404).build());
  when(client.listParts(any(ListPartsRequest.class))).thenThrow(S3Exception.builder().statusCode(404).build());
 }
 private UploadPartResponse part(int number) {
  UploadPartResponse.Builder response=UploadPartResponse.builder().eTag("etag-"+number).checksumCRC32("AAAAAA==");
  response.responseMetadata(S3ResponseMetadata.create(null));
  response.sdkHttpResponse(SdkHttpResponse.builder().statusCode(200).build());return response.build();
 }
 private Path archive(long size) throws IOException {
  Path p=root.resolve(UUID.randomUUID()+".tgz");
  try(var f=new RandomAccessFile(p.toFile(),"rw")) { f.setLength(size);f.write(new byte[]{31,(byte)139,0,0}); }
  return p;
 }
 @Test void retryStreamReopensSameRangeAndRejectsTruncation() throws Exception {
  Path p=root.resolve("bytes");Files.write(p,new byte[]{0,1,2,3,4,5});
  try(var provider=new MultipartArchiveUploader.FileSlice(p,2,3)) {
   assertThat(provider.newStream().readAllBytes()).containsExactly(2,3,4);
   assertThat(provider.newStream().readAllBytes()).containsExactly(2,3,4);
  }
  try(var provider=new MultipartArchiveUploader.FileSlice(p,4,4)) {
   assertThatThrownBy(()->provider.newStream().readAllBytes()).isInstanceOf(EOFException.class);
  }
 }
 @Test void boundedConcurrencyAndOrderedCompletionWithShortLastPart() throws Exception {
  AtomicInteger active=new AtomicInteger(),peak=new AtomicInteger();
  CountDownLatch firstWave=new CountDownLatch(4);
  List<Long> lengths=Collections.synchronizedList(new ArrayList<>());
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenAnswer(call->{
   UploadPartRequest request=call.getArgument(0);RequestBody body=call.getArgument(1);
   peak.accumulateAndGet(active.incrementAndGet(),Math::max);firstWave.countDown();
   try {
    assertThat(firstWave.await(5,TimeUnit.SECONDS)).isTrue();
    assertThat(body.optionalContentLength().orElseThrow()).isEqualTo(request.contentLength());
    lengths.add(request.contentLength());return part(request.partNumber());
   }finally { active.decrementAndGet(); }
  });
  long size=MultipartArchiveUploader.PART_BYTES*4+123;
  try(var uploader=new MultipartArchiveUploader(client,4)) { uploader.upload(BUCKET,KEY,archive(size),"application/gzip",size,"attempt"); }
  assertThat(peak.get()).isEqualTo(4);assertThat(lengths).hasSize(5).contains(123L);
  var completion=org.mockito.ArgumentCaptor.forClass(CompleteMultipartUploadRequest.class);
  verify(client).completeMultipartUpload(completion.capture());
  assertThat(completion.getValue().multipartUpload().parts()).extracting(CompletedPart::partNumber).containsExactly(1,2,3,4,5);
  verify(client,never()).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
 }
 @Test void failureDrainsOtherRequestsBeforeAbortAndDoesNotComplete() throws Exception {
  CountDownLatch otherStarted=new CountDownLatch(1),releaseOther=new CountDownLatch(1);
  AtomicBoolean drained=new AtomicBoolean();
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenAnswer(call->{
   UploadPartRequest request=call.getArgument(0);
   if(request.partNumber()==1) { assertThat(otherStarted.await(5,TimeUnit.SECONDS)).isTrue();releaseOther.countDown();throw S3Exception.builder().statusCode(503).build(); }
   otherStarted.countDown();assertThat(releaseOther.await(5,TimeUnit.SECONDS)).isTrue();drained.set(true);return part(request.partNumber());
  });
  when(client.abortMultipartUpload(any(AbortMultipartUploadRequest.class))).thenAnswer(call->{assertThat(drained.get()).isTrue();return AbortMultipartUploadResponse.builder().build();});
  try(var uploader=new MultipartArchiveUploader(client,2)) {
   assertThatThrownBy(()->uploader.upload(BUCKET,KEY,archive(40_000_000),"application/gzip",40_000_000,"attempt")).isInstanceOf(IOException.class);
  }
  verify(client).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
  verify(client,never()).completeMultipartUpload(any(CompleteMultipartUploadRequest.class));
 }
 @Test void lostCompletionAcknowledgementAcceptsOnlyMatchingAttemptAndLength() throws Exception {
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenReturn(part(1));
  when(client.completeMultipartUpload(any(CompleteMultipartUploadRequest.class))).thenThrow(new RuntimeException("lost response"));
  when(client.headObject(any(HeadObjectRequest.class))).thenReturn(HeadObjectResponse.builder().contentLength(32L).metadata(Map.of("ds2l-upload-attempt","mine")).build());
  try(var uploader=new MultipartArchiveUploader(client,1)) { uploader.upload(BUCKET,KEY,archive(32),"application/gzip",32,"mine"); }
  verify(client,never()).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
  try(var uploader=new MultipartArchiveUploader(client,1)) {
   assertThatThrownBy(()->uploader.upload(BUCKET,KEY,archive(32),"application/gzip",32,"other")).isInstanceOf(RuntimeException.class);
  }
  verify(client).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
 }
 @Test void cleanupPermissionFailureIsNotReportedAsSuccess() throws Exception {
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenThrow(new RuntimeException("part failure"));
  when(client.abortMultipartUpload(any(AbortMultipartUploadRequest.class))).thenThrow(S3Exception.builder().statusCode(403).build());
  try(var uploader=new MultipartArchiveUploader(client,1)) {
   assertThatThrownBy(()->uploader.upload(BUCKET,KEY,archive(32),"application/gzip",32,"mine"))
    .isInstanceOf(IOException.class).satisfies(error->assertThat(error.getCause().getSuppressed()).hasSize(1));
  }
 }
 @RepeatedTest(50) void callerInterruptionWaitsForPartAndPreservesInterruptAfterCleanup() throws Exception {
  CountDownLatch started=new CountDownLatch(1),release=new CountDownLatch(1);
  AtomicBoolean restored=new AtomicBoolean(),drained=new AtomicBoolean();AtomicReference<Throwable> error=new AtomicReference<>();
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenAnswer(call->{
   started.countDown();assertThat(release.await(5,TimeUnit.SECONDS)).isTrue();drained.set(true);return part(1);
  });
  when(client.abortMultipartUpload(any(AbortMultipartUploadRequest.class))).thenAnswer(call->{
   assertThat(drained.get()).isTrue();assertThat(Thread.currentThread().isInterrupted()).isFalse();
   return AbortMultipartUploadResponse.builder().build();
  });
  Path source=archive(32);
  try(var uploader=new MultipartArchiveUploader(client,1)) {
   Thread caller=new Thread(()->{
    try { uploader.upload(BUCKET,KEY,source,"application/gzip",32,"mine"); }
    catch(Throwable failure) { error.set(failure);restored.set(Thread.currentThread().isInterrupted()); }
   });
   try {
    caller.start();assertThat(started.await(5,TimeUnit.SECONDS)).isTrue();caller.interrupt();release.countDown();caller.join(5000);
    assertThat(caller.isAlive()).isFalse();assertThat(error.get()).isInstanceOf(IOException.class);assertThat(restored.get()).isTrue();
   } finally { release.countDown();caller.join(5000); }
  }
  verify(client).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
  verify(client,never()).completeMultipartUpload(any(CompleteMultipartUploadRequest.class));
 }
 @Test void interruptDuringCreateAbortsWithoutSubmittingPartsAndRestoresFlag() throws Exception {
  when(client.createMultipartUpload(any(CreateMultipartUploadRequest.class))).thenAnswer(call->{
   Thread.currentThread().interrupt();return CreateMultipartUploadResponse.builder().uploadId("owned-upload").build();
  });
  when(client.abortMultipartUpload(any(AbortMultipartUploadRequest.class))).thenAnswer(call->{
   assertThat(Thread.currentThread().isInterrupted()).isFalse();return AbortMultipartUploadResponse.builder().build();
  });
  Path source=archive(32);
  try(var uploader=new MultipartArchiveUploader(client,1)) {
   assertThatThrownBy(()->uploader.upload(BUCKET,KEY,source,"application/gzip",32,"mine")).isInstanceOf(IOException.class);
   assertThat(Thread.currentThread().isInterrupted()).isTrue();
  } finally { Thread.interrupted(); }
  verify(client).abortMultipartUpload(any(AbortMultipartUploadRequest.class));
  verify(client,never()).uploadPart(any(UploadPartRequest.class),any(RequestBody.class));
  verify(client,never()).completeMultipartUpload(any(CompleteMultipartUploadRequest.class));
 }
 @Test void smallArchivesUseSinglePutAndExistingDownloadTargetIsPreserved() throws Exception {
  String key=UUID.randomUUID().toString();Path target=root.resolve("existing");Files.writeString(target,"preserve");
  try(var store=new UploadArchiveStore(BUCKET,client,true,4,1073741824L)) {
   store.put(key,archive(64));
   assertThatThrownBy(()->store.fetch(key,target)).isInstanceOf(FileAlreadyExistsException.class);
  }
  verify(client).putObject(any(Consumer.class),any(RequestBody.class));
  verify(client,never()).createMultipartUpload(any(CreateMultipartUploadRequest.class));
  assertThat(Files.readString(target)).isEqualTo("preserve");
 }
 @Test void truncatedDownloadNeverPublishesAndCanRetryWithoutPartialFiles() throws Exception {
  String key=UUID.randomUUID().toString();Path target=root.resolve("download");
  when(client.getObject(any(Consumer.class))).thenAnswer(call->new ResponseInputStream<>(GetObjectResponse.builder().contentLength(100L).build(),new ByteArrayInputStream(new byte[]{1,2,3})));
  try(var store=new UploadArchiveStore(BUCKET,client,false,4,1073741824L)) {
   assertThatThrownBy(()->store.fetch(key,target)).isInstanceOf(IOException.class);
   assertThat(target).doesNotExist();
   try(var paths=Files.list(root)) { assertThat(paths.toList()).isEmpty(); }
   when(client.getObject(any(Consumer.class))).thenAnswer(call->new ResponseInputStream<>(GetObjectResponse.builder().contentLength(3L).build(),new ByteArrayInputStream(new byte[]{1,2,3})));
   store.fetch(key,target);assertThat(Files.readAllBytes(target)).containsExactly(1,2,3);
  }
 }
 @Test void conservativeSizeGuardKeepsSmallFilesSingleAndAllowsLargeMultipart() throws Exception {
  when(client.uploadPart(any(UploadPartRequest.class),any(RequestBody.class))).thenAnswer(call->part(((UploadPartRequest)call.getArgument(0)).partNumber()));
  try(var store=new UploadArchiveStore(BUCKET,client,true,4,1073741824L)) {
   store.put(UUID.randomUUID().toString(),archive(109696439));
   store.put(UUID.randomUUID().toString(),archive(1073741824L));
   verify(client,times(2)).putObject(any(Consumer.class),any(RequestBody.class));
   verify(client,never()).createMultipartUpload(any(CreateMultipartUploadRequest.class));
   store.put(UUID.randomUUID().toString(),archive(1073741825L));
   verify(client).createMultipartUpload(any(CreateMultipartUploadRequest.class));
   verify(client).completeMultipartUpload(any(CompleteMultipartUploadRequest.class));
  }
 }
}
